        const st = subSt(fp.sub, parent);
        const op = st === "p" ? 0.32 : st === "s" ? 0.16 : 0.036;
        return <path key={`${k}f${i}`} d={fp.d} fill="none" stroke="rgba(255,255,255,0.88)" strokeWidth={0.38} opacity={op} strokeLinecap="round"/>;
