  // to "shift" on rotation. (qa: workout-rest-motivational-phrases)
  const watermarkPhrase = useMemo(() => {
    const idx = Math.floor(Math.random() * WATERMARK_PHRASES.length);
    return WATERMARK_PHRASES[idx];
  }, []);

  // ── Theme ──
