  useEffect(() => {
    if (!user) return;
    try {
      if (!localStorage.getItem(TUTORIAL_STORAGE_KEY)) {
        setShowTutorial(true);
      }
    } catch {}
  }, [user?.id]);

  // Weekly recap — fires once per ISO week on Sunday onwards. Only when
