  useEffect(() => {
    if (!user || Object.keys(history).length === 0) return;
    if (shouldShowWeeklyRecap()) {
      const recap = buildWeeklyRecap(history);
      if (recap.sessions > 0) {
        setRecapShown(recap);
        markRecapShown();
      }
    }
  }, [user?.id, Object.keys(history).length]);

  const refreshUser = useCallback(() => {
    fetch("/api/auth").then(r => r.json()).then(data => {
      if (data.user) {
        setUser({ id: data.user.id, username: data.user.username, role: data.user.role ?? "user", extraRoles: data.user.extraRoles ?? [], roleRequest: data.user.roleRequest ?? null, createdAt: data.user.createdAt });
        if (data.user.mustReset) setMustResetPassword(true);
        if (typeof Notification !== "undefined" && Notification.permission === "granted") {
          subscribeToPush().then(s => setNotifStatus(s));
        }
      }
      setAuthLoading(false);
    }).catch(() => setAuthLoading(false));
  }, []);

  useEffect(() => {
    refreshUser();
  }, []);

  // Re-check user on every realistic 'app reopened' trigger so an
  // admin-issued force-reset (mustResetPassword=true) actually lands
  // on the client mid-session, not just after a fresh login.
  // - visibilitychange: tab/PWA returns to foreground (most reliable)
  // - pageshow: iOS Safari back-forward cache + PWA wake-up (covers
  //   the case where visibilitychange doesn't fire because the page
  //   was restored from bfcache rather than re-rendered)
  // - focus: desktop window focus
  // - 60s interval: foreground-active sessions where none of the
  //   above ever fire (long single-tab use)
  // (qa: auth-must-reset)
  useEffect(() => {
    const onVisible = () => { if (document.visibilityState === "visible") refreshUser(); };
    const onPageShow = () => refreshUser();
    const onFocus = () => refreshUser();
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("pageshow", onPageShow);
    window.addEventListener("focus", onFocus);
    const id = setInterval(refreshUser, 60_000);
    return () => {
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("pageshow", onPageShow);
      window.removeEventListener("focus", onFocus);
      clearInterval(id);
    };
  }, [refreshUser]);

  // Minimum splash duration so the fall animation completes
  useEffect(() => {
    // 2.4s lets the impact + shockwave land (0.85s), the tagline fade
    // in (1.25s), AND one full light-sweep cycle across the logo
    // (1.0s delay + 1.4s duration = completes at 2.4s). Any shorter
    // and the user only sees a partial sweep. (qa: splash-polish)
    const t = setTimeout(() => setSplashDone(true), 2400);
    return () => clearTimeout(t);
  }, []);

